// Scanlines: every other row of the picture darkened by `strength`.
kernel scanline.effect@1 {
    requires { field.read; field.write; }
    input source: Image;
    param strength: Float = 0.5;
    output result: Image;
    compute {
        let c = sample(source);
        let dark = coord().y % 2 == 1;
        return if dark { vec4(c.rgb * (1.0 - strength), c.a) } else { c };
    }
}

