// A picture, shown through the scanlines an agent added while it ran.
use "kernels/";

node picture: picture.draw@1 { domain = vec2(160, 120); }
node scan: scanline.effect@1 { source <- picture.result; strength = 0.5; }

output result <- scan.result;

